import React, { useEffect, useState } from "react";
import getVotingContract from '../utils/getVotingContract';

const VotingPage = () => {
  const [candidates, setCandidates] = useState([]);
  const [hasVoted, setHasVoted] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchCandidates = async () => {
      try {
        const contract = await getVotingContract();
        const count = await contract.getCandidateCount();
        const temp = [];

        for (let i = 0; i < count; i++) {
          const name = await contract.getCandidateName(i);
          const votes = await contract.getVoteCount(i);
          temp.push({ name, votes: votes.toString(), index: i });
        }

        setCandidates(temp);

        // Check if current user has already voted
        const accounts = await window.ethereum.request({ method: "eth_accounts" });
        const voted = await contract.hasVoted(accounts[0]);
        setHasVoted(voted);

        setLoading(false);
      } catch (err) {
        console.error("Error loading data:", err);
      }
    };

    fetchCandidates();
  }, []);

  const handleVote = async (index) => {
    const contract = await getVotingContract();
    try {
      const tx = await contract.vote(index);
      await tx.wait();
      alert("Vote submitted!");
      window.location.reload(); // Reload to update vote counts
    } catch (err) {
      alert("Voting failed. Maybe already voted?");
      console.error(err);
    }
  };

  if (loading) return <div className="text-center mt-5">Loading candidates...</div>;

  return (
    <div className="container mt-5">
      <h2 className="mb-4">Vote for Your Candidate</h2>
      <table className="table table-bordered text-center">
        <thead className="table-dark">
          <tr>
            <th>#</th>
            <th>Name</th>
            <th>Votes</th>
            <th>Action</th>
          </tr>
        </thead>
        <tbody>
          {candidates.map((cand, idx) => (
            <tr key={idx}>
              <td>{idx + 1}</td>
              <td>{cand.name}</td>
              <td>{cand.votes}</td>
              <td>
                {hasVoted ? (
                  <button className="btn btn-secondary" disabled>Voted</button>
                ) : (
                  <button className="btn btn-primary" onClick={() => handleVote(cand.index)}>Vote</button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default VotingPage;
